1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; margin-top: 6px; }
26	  .preview .mini { width: 20px; height: 20px; background: transparent; }
27	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
28	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
29	  .help { font-size: 13px; color: #9097a6; }
30	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
31	  button {
32	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
33	    font: inherit; font-weight: 600; cursor: pointer;
34	  }
35	</style>
36	</head>
37	<body>
38	<div class="game">
39	  <div class="board" data-testid="board"></div>
40	  <div class="panel">
41	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
42	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
43	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
44	    <div class="stat"><div class="label">Next</div><div class="preview" data-testid="next"></div></div>
45	    <div class="status" data-testid="status"></div>
46	    <button type="button" id="new-game">New game</button>
47	    <div class="help">
48	      <kbd>←</kbd> <kbd>→</kbd> move<br>
49	      <kbd>↓</kbd> soft drop<br>
50	      <kbd>Space</kbd> hard drop
51	    </div>
52	  </div>
53	</div>
54	<script>
55	(function () {
56	  'use strict';
57	
58	  var ROWS = 20, COLS = 10;
59	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
60	  var COLORS = {
61	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
62	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
63	  };
64	  // Spawn orientation, as [row, col] offsets from the piece origin.
65	  var SHAPES = {
66	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
67	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
68	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
69	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
70	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
71	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
72	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
73	  };
74	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
75	  var GRAVITY_MS = 1000;
76	
77	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
78	  var board, current, queue, bag, score, level, lines, status, timer = null;
79	
80	  // ---- DOM ----
81	  var boardEl = document.querySelector('[data-testid="board"]');
82	  var scoreEl = document.querySelector('[data-testid="score"]');
83	  var levelEl = document.querySelector('[data-testid="level"]');
84	  var linesEl = document.querySelector('[data-testid="lines"]');
85	  var nextEl = document.querySelector('[data-testid="next"]');
86	  var statusEl = document.querySelector('[data-testid="status"]');
87	  var cellEls = [];
88	  var miniEls = [];
89	
90	  for (var r = 0; r < ROWS; r++) {
91	    cellEls.push([]);
92	    for (var c = 0; c < COLS; c++) {
93	      var el = document.createElement('div');
94	      el.className = 'cell';
95	      el.setAttribute('data-testid', 'cell');
96	      el.setAttribute('data-row', String(r));
97	      el.setAttribute('data-col', String(c));
98	      boardEl.appendChild(el);
99	      cellEls[r].push(el);
100	    }
101	  }
102	  for (var mr = 0; mr < 2; mr++) {
103	    miniEls.push([]);
104	    for (var mc = 0; mc < 4; mc++) {
105	      var m = document.createElement('div');
106	      m.className = 'mini';
107	      nextEl.appendChild(m);
108	      miniEls[mr].push(m);
109	    }
110	  }
111	
112	  function paint(el, type) {
113	    el.setAttribute('data-filled', type ? 'true' : 'false');
114	    el.setAttribute('data-piece', type || '');
115	    el.style.backgroundColor = type ? COLORS[type] : '';
116	  }
117	
118	  function render() {
119	    var view = board.map(function (row) { return row.slice(); });
120	    if (current) {
121	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
122	    }
123	    for (var r = 0; r < ROWS; r++) {
124	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
125	    }
126	
127	    var upcoming = queue[0] || '';
128	    for (var mr = 0; mr < 2; mr++) {
129	      for (var mc = 0; mc < 4; mc++) paint(miniEls[mr][mc], '');
130	    }
131	    if (upcoming) {
132	      SHAPES[upcoming].forEach(function (p) { paint(miniEls[p[0]][p[1]], upcoming); });
133	    }
134	
135	    scoreEl.textContent = String(score);
136	    levelEl.textContent = String(level);
137	    linesEl.textContent = String(lines);
138	    statusEl.textContent = status === 'over' ? 'Game over' : '';
139	  }
140	
141	  // ---- Pieces ----
142	  function randomPiece() {
143	    if (!bag.length) {
144	      bag = TYPES.slice();
145	      for (var i = bag.length - 1; i > 0; i--) {
146	        var j = Math.floor(Math.random() * (i + 1));
147	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
148	      }
149	    }
150	    return bag.pop();
151	  }
152	
153	  function takeNext() {
154	    if (!queue.length) queue.push(randomPiece());
155	    var type = queue.shift();
156	    if (!queue.length) queue.push(randomPiece());
157	    return type;
158	  }
159	
160	  function pieceCells(piece) {
161	    return SHAPES[piece.type].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
162	  }
163	
164	  function fits(cells) {
165	    return cells.every(function (p) {
166	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
167	    });
168	  }
169	
170	  function spawn() {
171	    var type = takeNext();
172	    var piece = { type: type, row: 0, col: SPAWN_COL[type] };
173	    if (!fits(pieceCells(piece))) {
174	      current = null;
175	      status = 'over';
176	      stopTimer();
177	      return;
178	    }
179	    current = piece;
180	  }
181	
182	  function move(dr, dc) {
183	    if (!current) return false;
184	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc };
185	    if (!fits(pieceCells(moved))) return false;
186	    current = moved;
187	    return true;
188	  }
189	
190	  function lock() {
191	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
192	    current = null;
193	    spawn();
194	  }
195	
196	  // One gravity step. The real timer and tick() both run exactly this.
197	  function gravityStep() {
198	    if (status !== 'running' || !current) return;
199	    if (!move(1, 0)) lock();
200	  }
201	
202	  function gravity() {
203	    gravityStep();
204	    render();
205	  }
206	
207	  function stopTimer() {
208	    if (timer !== null) { clearInterval(timer); timer = null; }
209	  }
210	
211	  function startTimer() {
212	    stopTimer();
213	    timer = setInterval(gravity, GRAVITY_MS);
214	  }
215	
216	  // ---- Actions ----
217	  function input(action) {
218	    if (status !== 'running' || !current) return;
219	    if (action === 'left') move(0, -1);
220	    else if (action === 'right') move(0, 1);
221	    else if (action === 'softDrop') gravityStep();
222	    else if (action === 'hardDrop') {
223	      while (move(1, 0)) { /* fall to the lowest reachable row */ }
224	      lock();
225	    }
226	    render();
227	  }
228	
229	  function toQueue(list) {
230	    return (Array.isArray(list) ? list : [])
231	      .map(function (t) { return String(t).toUpperCase(); })
232	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
233	  }
234	
235	  function newGame(list) {
236	    board = [];
237	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
238	    bag = [];
239	    queue = toQueue(list);
240	    score = 0;
241	    level = 1;
242	    lines = 0;
243	    status = 'running';
244	    current = null;
245	    spawn();
246	    if (status === 'running') startTimer();
247	    render();
248	  }
249	
250	  function setQueue(list) {
251	    queue = toQueue(list);
252	    render();
253	  }
254	
255	  function setBoard(rows) {
256	    for (var r = 0; r < ROWS; r++) {
257	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
258	      for (var c = 0; c < COLS; c++) {
259	        var ch = line.charAt(c).toUpperCase();
260	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
261	      }
262	    }
263	    render();
264	  }
265	
266	  function getBoard() {
267	    return board.map(function (row) {
268	      return row.map(function (t) { return t || '.'; }).join('');
269	    });
270	  }
271	
272	  function getState() {
273	    return {
274	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
275	      next: queue.slice(),
276	      score: score,
277	      level: level,
278	      lines: lines,
279	      status: status
280	    };
281	  }
282	
283	  function tick(n) {
284	    var steps = n === undefined ? 1 : n;
285	    for (var i = 0; i < steps; i++) gravity();
286	  }
287	
288	  window.__tetris = {
289	    newGame: newGame,
290	    setQueue: setQueue,
291	    setBoard: setBoard,
292	    tick: tick,
293	    input: input,
294	    getBoard: getBoard,
295	    getState: getState
296	  };
297	
298	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
299	  document.addEventListener('keydown', function (e) {
300	    var action = KEYS[e.key];
301	    if (!action) return;
302	    e.preventDefault();
303	    input(action);
304	  });
305	  document.getElementById('new-game').addEventListener('click', function (e) {
306	    e.currentTarget.blur();
307	    newGame();
308	  });
309	
310	  newGame();
311	})();
312	</script>
313	</body>
314	</html>
