p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep("""      <kbd>←</kbd> <kbd>→</kbd> move<br>""","""      <kbd>←</kbd> <kbd>→</kbd> move<br>
      <kbd>↑</kbd> rotate<br>""")
rep("""  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
  var GRAVITY_MS = 1000;
""","""  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
  var GRAVITY_MS = 1000;

  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
  var ROTATIONS = {};
  TYPES.forEach(function (t) {
    var n = t === 'O' ? 2 : 3;
    var states = [SHAPES[t]];
    for (var k = 1; k < 4; k++) {
      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
    }
    ROTATIONS[t] = states;
  });
  ROTATIONS.I = [
    SHAPES.I,
    [[0, 2], [1, 2], [2, 2], [3, 2]],
    [[1, 0], [1, 1], [1, 2], [1, 3]],
    [[0, 1], [1, 1], [2, 1], [3, 1]]
  ];
  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
  var KICKS = [0, -1, 1, -2, 2];

  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
  // right move during the delay restarts it, at most MAX_RESTARTS times per piece. Hard drop
  // locks at once.
  var LOCK_TICKS = 2;
  var MAX_RESTARTS = 3;
""")
rep("""    return SHAPES[piece.type].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });""",
"""    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });""")
rep("""    var piece = { type: type, row: 0, col: SPAWN_COL[type] };""",
"""    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };""")
rep("""  function move(dr, dc) {
    if (!current) return false;
    var moved = { type: current.type, row: current.row + dr, col: current.col + dc };
    if (!fits(pieceCells(moved))) return false;
    current = moved;
    return true;
  }
""","""  function move(dr, dc) {
    if (!current) return false;
    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
    if (!fits(pieceCells(moved))) return false;
    current.row = moved.row;
    current.col = moved.col;
    return true;
  }

  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
  function shift(dc) {
    if (!move(0, dc)) return;
    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
      current.lockTicks = 0;
      current.restarts++;
    }
  }

  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
  function rotateCW() {
    if (!current) return false;
    var rot = (current.rot + 1) % 4;
    for (var i = 0; i < KICKS.length; i++) {
      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
      if (fits(pieceCells(turned))) {
        current.col = turned.col;
        current.rot = rot;
        return true;
      }
    }
    return false;
  }
""")
rep("""    if (!move(1, 0)) lock();
  }""","""    if (move(1, 0)) {
      current.lockTicks = 0;
      return;
    }
    current.lockTicks++;
    if (current.lockTicks >= LOCK_TICKS) lock();
  }""")
rep("""    if (action === 'left') move(0, -1);
    else if (action === 'right') move(0, 1);""","""    if (action === 'left') shift(-1);
    else if (action === 'right') shift(1);
    else if (action === 'rotateCW') rotateCW();""")
rep("""ArrowRight: 'right', ""","""ArrowRight: 'right', ArrowUp: 'rotateCW', """)
open(p,'w').write(s)
EOF
